WITH kept_keys AS (SELECT event_type, id FROM web_events EXCEPT ALL SELECT event_type, id FROM web_events WHERE page = '/checkout'), reconciled AS (SELECT s.* FROM web_events s INNER JOIN kept_keys k ON s.event_type = k.event_type AND s.id = k.id) SELECT CASE WHEN duration_sec >= 451 THEN 'HIGH' ELSE 'LOW' END AS duration_sec_tier, ROUND(AVG(duration_sec), 2) AS avg_duration_sec, ROUND(SUM(duration_sec) / NULLIF(COUNT(CASE WHEN event_type = 'page_view' THEN 1 END), 0), 2) AS duration_sec_per_page_view, APPROX_PERCENTILE(duration_sec, ARRAY(0.25, 0.5, 0.75)) AS duration_sec_quartiles FROM reconciled GROUP BY CASE WHEN duration_sec >= 451 THEN 'HIGH' ELSE 'LOW' END ORDER BY duration_sec_per_page_view NULLS LAST;
